contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 _minSum, uint256 _logSeed, uint256 _amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (_amount)); require(_amount <= 1000000000000000000000000000000);
        require(address(this).balance >= _amount);

        // Optionally drive some setup through public entry points:
        c.SetMinSum(_minSum); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(uint160(0x1000 + (_logSeed % 0x1000)))); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        uint256 beforeVal = c.balances(address(this)); if (__ESBMC_reverted()) return;

        c.Deposit{value: _amount}(); if (__ESBMC_reverted()) return;

        uint256 afterVal = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(afterVal == beforeVal + _amount);
    }

    receive() external payable {}
}

