pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 _minSum, uint256 _logSeed, uint256 _amount) internal {
        _amount = bound(_amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= _amount);
        try c.SetMinSum(_minSum) {} catch { return; }
        try c.SetLogFile(address(uint160(0x1000 + (_logSeed % 0x1000)))) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 beforeVal;
        try c.balances(address(this)) returns (uint256 __r) { beforeVal = __r; } catch { return; }
        try c.Deposit{value: _amount}() {} catch { return; }
        uint256 afterVal;
        try c.balances(address(this)) returns (uint256 __r) { afterVal = __r; } catch { return; }
        assertTrue(afterVal == beforeVal + _amount);
    }

    function testFuzz_run(uint256 _minSum, uint256 _logSeed, uint256 _amount) public {
        _run(_minSum, _logSeed, _amount);
    }

    receive() external payable {}
}
